-- (DECFLOAT, BINARY, VARBINARY, BLOB, CLOB, BOOLEAN, TIMESTAMP(12)) and
-- the alias. Today RUNSQLSTM refuses the whole file (SQL0084); run it
-- after hlinv.sql once the engine has them, and enable its test in
-- tools/conformance/tests/qap_setup.rs (QAP_TYPES).
-- RUNSQLSTM SRCSTMF('/home/QSECOFR/hlinv-types.sql') COMMIT(*NONE) NAMING(*SQL)

CREATE TABLE HLTEST.NEWTYPES (
  ID INTEGER NOT NULL PRIMARY KEY,
  C_DECFLOAT DECFLOAT(34),
  C_CLOB CLOB(65536),
  C_BINARY BINARY(4),
  C_VARBINARY FOR COLUMN C_VARBIN VARBINARY(16),
  C_BLOB BLOB(65536),
  C_TS12 TIMESTAMP(12),
  C_BOOLEAN BOOLEAN
);
LABEL ON TABLE HLTEST.NEWTYPES IS 'The types the engine is being given';
INSERT INTO HLTEST.NEWTYPES VALUES
