  (2, 1.5E-30, '', BX'00000000', BX'', BLOB(X''), '1970-01-01-00.00.00.000000000001', FALSE),
  (3, DECFLOAT('Infinity'), 'line break', BX'FFFFFFFF', BX'FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF', BLOB(X''), '0001-01-01-00.00.00.000000000000', TRUE),
  (4, DECFLOAT('-Infinity'), '€', BX'DEADBEEF', BX'7F', BLOB(X'01'), '9999-12-31-23.59.59.999999999999', FALSE),
  (5, DECFLOAT('NaN'), 'z', BX'09090909', BX'8081', BLOB(X'0203'), '2000-02-29-12.00.00.500000000000', TRUE),
  (6, DECFLOAT('sNaN'), 'A long text', BX'01020304', BX'0102', BLOB(X'255044462D312E34'), '2026-11-02-09.14.03.123456789012', TRUE),
  (7, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

-- The alias over ASSETS (the engine parses CREATE ALIAS, runs it not yet).
CREATE ALIAS HLINV.HW FOR HLINV.ASSETS;
LABEL ON ALIAS HLINV.HW IS 'Hardware assets';
